export interface MetaProps {
  title: string;
  description: string;
  canonical: string;
  noindex?: boolean;
  ogImage?: string;
}

interface CountryRef {
  name: string;
  nameGenitive: string;
  nameLocative: string;
}

interface CityRef {
  name: string;
  nameLocative: string;
}

interface MetaOptions {
  country?: CountryRef;
  city?: CityRef;
  baseUrl: string;
  path: string;
}

import { SITE_NAME } from './constants';

// generateMeta's service param → the og image file generated by scripts/gen-og.mjs
const OG_IMAGE_BY_SERVICE: Record<string, string> = {
  autopodbor: 'autopodbor',
  vykup: 'vykup',
  proverka: 'proverka',
};

export function generateMeta(
  service: 'autopodbor' | 'vykup' | 'proverka',
  options: MetaOptions
): MetaProps {
  const { country, city, baseUrl, path } = options;
  const canonical = `${baseUrl}${path}`;
  const ogImage = `${baseUrl}/og/${OG_IMAGE_BY_SERVICE[service]}.png`;

  switch (service) {
    case 'autopodbor': {
      const location = city
        ? `в ${city.nameLocative}`
        : `в ${country!.nameLocative}`;
      return {
        title: `Автоподбор под ключ ${location} | ${SITE_NAME}`,
        description: `Автоподбор под ключ ${location}: поиск, независимая проверка, сопровождение сделки и доставка до вашего города. Оставьте заявку — свяжемся в Telegram.`,
        canonical,
        ogImage,
      };
    }
    case 'vykup': {
      return {
        title: `Выкуп авто в ${country!.nameLocative} на иностранных номерах — срочно | ${SITE_NAME}`,
        description: `Срочный выкуп автомобилей в ${country!.nameLocative} на любых номерах — иностранных, российских или сербских. Оценка онлайн, оформление за 1 день, перевод в день сделки.`,
        canonical,
        ogImage,
      };
    }
    case 'proverka': {
      return {
        title: `Проверка авто в ${country!.nameLocative} перед покупкой | ${SITE_NAME}`,
        description: `Независимая проверка автомобиля в ${country!.nameLocative}. Выезд эксперта, осмотр кузова и ходовой, отчёт. Защитите себя от покупки битого авто.`,
        canonical,
        ogImage,
      };
    }
    default: {
      const _exhaustive: never = service;
      throw new Error(`generateMeta: unhandled service ${_exhaustive}`);
    }
  }
}

export function generateServiceSchema(name: string, areaServed: string | string[], url: string) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Service',
    name,
    // Organization, not LocalBusiness: the business has no physical storefront
    // or service address — it operates cross-border, entirely through Telegram.
    provider: { '@type': 'Organization', name: SITE_NAME },
    areaServed,
    url,
  };
}

// Homepage/business-entity schema. Organization (not LocalBusiness — no address,
// no fixed service location) with sameAs pointing at the actual public profiles
// and a contactPoint for the real (Telegram-only) contact channel, instead of
// fabricating an address/telephone/geo the business doesn't have.
export function generateOrganizationSchema(options: {
  url: string;
  description: string;
  areaServed: string[];
  sameAs: string[];
  contactUrl: string;
}) {
  const { url, description, areaServed, sameAs, contactUrl } = options;
  return {
    '@context': 'https://schema.org',
    '@type': 'Organization',
    name: SITE_NAME,
    description,
    url,
    logo: `${url}/apple-touch-icon.png`,
    areaServed,
    sameAs,
    contactPoint: {
      '@type': 'ContactPoint',
      contactType: 'customer service',
      url: contactUrl,
      availableLanguage: ['Russian', 'English'],
    },
  };
}

// Case bodies open with a hand-written, case-specific hook line — use it instead
// of a templated description so each case page reads as unique, not boilerplate.
export function excerptFromMarkdown(markdown: string, maxLen = 140): string {
  const firstParagraph = markdown.trim().split(/\n\s*\n/)[0] ?? '';
  const plain = firstParagraph
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/[*_`]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  if (plain.length <= maxLen) return plain;
  return plain.slice(0, maxLen).replace(/\s+\S*$/, '') + '…';
}

export function generateArticleSchema(options: {
  headline: string;
  description: string;
  image?: string;
  datePublished: Date;
  url: string;
}) {
  const { headline, description, image, datePublished, url } = options;
  return {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline,
    description,
    image,
    datePublished: datePublished.toISOString(),
    author: { '@type': 'Organization', name: SITE_NAME },
    publisher: { '@type': 'Organization', name: SITE_NAME },
    mainEntityOfPage: url,
  };
}
